  databaseSql: {"1667":"SELECT user_id,\n       CONCAT(UPPER(LEFT(name, 1)), LOWER(SUBSTRING(name, 2))) AS name\nFROM Users\nORDER BY user_id;","1683":"SELECT tweet_id\nFROM Tweets\nWHERE CHAR_LENGTH(content) > 15;","1693":"SELECT date_id, make_name,\n       COUNT(DISTINCT lead_id) AS unique_leads,\n       COUNT(DISTINCT partner_id) AS unique_partners\nFROM DailySales\nGROUP BY date_id, make_name;","1729":"SELECT user_id, COUNT(*) AS followers_count\nFROM Followers\nGROUP BY user_id\nORDER BY user_id;","1741":"SELECT event_day AS day, emp_id,\n       SUM(out_time - in_time) AS total_time\nFROM Employees\nGROUP BY event_day, emp_id;","1757":"SELECT product_id\nFROM Products\nWHERE low_fats = 'Y' AND recyclable = 'Y';","1821":"SELECT customer_id\nFROM Customers\nWHERE year = 2021 AND revenue > 0;","1873":"SELECT employee_id,\n       CASE WHEN MOD(employee_id, 2) = 1\n                 AND ASCII(LEFT(name, 1)) <> ASCII('M')\n            THEN salary ELSE 0 END AS bonus\nFROM Employees\nORDER BY employee_id;","1890":"SELECT user_id, MAX(time_stamp) AS last_stamp\nFROM Logins\nWHERE time_stamp >= '2020-01-01 00:00:00'\n  AND time_stamp < '2021-01-01 00:00:00'\nGROUP BY user_id;","1907":"SELECT 'Low Salary' AS category, COUNT(*) AS accounts_count\nFROM Accounts WHERE income < 20000\nUNION ALL\nSELECT 'Average Salary', COUNT(*)\nFROM Accounts WHERE income BETWEEN 20000 AND 50000\nUNION ALL\nSELECT 'High Salary', COUNT(*)\nFROM Accounts WHERE income > 50000;"},
